func stageBindFiles(
	config *clabRuntimeConfig,
	topologyName,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
	configMaps map[string]*stagedConfigMap,
) error {
	binds, err := config.Topology.GetNodeBinds(nodeName)
	if err != nil {
		return fmt.Errorf("failed parsing bind mounts for node %q: %w", nodeName, err)
	}
	if len(binds) == 0 {
		return nil
	}

	for _, bind := range binds {
		parsedBind, err := clabtypes.NewBindFromString(bind)
		if err != nil {
			return fmt.Errorf("failed parsing bind %q for node %q: %w", bind, nodeName, err)
		}
		if parsedBind.Src() == "" {
			continue
		}

		if err := stageSourcePathIntoConfigMaps(
			configMaps,
			topologyName,
			parsedBind.Src(),
			nodeName,
			topologyFileDir,
			topologyLabDir,
		); err != nil {
			return err
		}
	}

	return nil
}

// stageAdditionalNodeFiles covers path-bearing fields that containerlab normally resolves on
// the machine running the CLI. A device pod cannot see those paths unless the adapter copies
// them into the node's ConfigMap-backed file projection first.
func stageAdditionalNodeFiles(
	config *clabRuntimeConfig,
	topologyName,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
	configMaps map[string]*stagedConfigMap,
) error {
	pathsByField := map[string][]string{
		"env-files": config.Topology.GetNodeEnvFiles(nodeName),
	}

	// kind-specific config key whose values are paths that a device pod cannot
	// see unless they are staged into the node's ConfigMaps first.
	pathFields := map[string]bool{
		"copy-to-flash": true,
	}

	for _, entry := range config.Topology.GetNodeKindSpecificConfig(nodeName) {
		if !pathFields[entry.Key] {
			continue
		}

		paths, ok := entry.Value.([]any)
		if !ok {
			continue
		}

		pathsByField[entry.Key] = make([]string, 0, len(paths))
		for _, p := range paths {
			if s, ok := p.(string); ok {
				pathsByField[entry.Key] = append(pathsByField[entry.Key], s)
			}
		}
	}

	fieldNames := make([]string, 0, len(pathsByField))
	for fieldName := range pathsByField {
		fieldNames = append(fieldNames, fieldName)
	}
	sort.Strings(fieldNames)

	for _, fieldName := range fieldNames {
		for _, sourcePath := range pathsByField[fieldName] {
			if strings.TrimSpace(sourcePath) == "" {
				continue
			}

			if err := stageSourcePathIntoConfigMaps(
				configMaps,
				topologyName,
				sourcePath,
				nodeName,
				topologyFileDir,
				topologyLabDir,
			); err != nil {
				return fmt.Errorf(
					"failed staging %s path %q for node %q: %w",
					fieldName,
					sourcePath,
					nodeName,
					err,
				)
			}
		}
	}

	return nil
}

func stageSourcePathIntoConfigMaps(
	configMaps map[string]*stagedConfigMap,
	topologyName,
	sourcePath,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
) error {
	files, err := resolveLocalFiles(sourcePath, nodeName, topologyFileDir, topologyLabDir)
	if err != nil {
		return fmt.Errorf(
			"failed staging source path %q for node %q: %w",
			sourcePath,
			nodeName,
			err,
		)
	}

	for _, file := range files {
		if err := stageLocalFile(configMaps, topologyName, nodeName, file); err != nil {
			return err
		}
	}

	return nil
}

